def find_right_interval_brute(intervals):
    n = len(intervals)
    result = [-1] * n
    for i in range(n):
        best_start = float('inf')
        for j in range(n):                              # scan every OTHER interval
            if intervals[j][0] >= intervals[i][1] and intervals[j][0] < best_start:
                best_start = intervals[j][0]
                result[i] = j
    return result

