import java.util.*;

public class Main {
    static int[] findRightInterval(int[][] intervals) {
        int n = intervals.length;
        int[][] starts = new int[n][2];
        for (int i = 0; i < n; i++) starts[i] = new int[]{intervals[i][0], i};
        Arrays.sort(starts, (a, b) -> a[0] - b[0]);                   // sort once
        int[] result = new int[n];
        Arrays.fill(result, -1);
        for (int i = 0; i < n; i++) {
            int end = intervals[i][1];
            int lo = 0, hi = n - 1, ans = -1;
            while (lo <= hi) {                                            // binary search per query
                int mid = (lo + hi) / 2;
                if (starts[mid][0] >= end) { ans = mid; hi = mid - 1; }
                else lo = mid + 1;
            }
            if (ans != -1) result[i] = starts[ans][1];
        }
        return result;
    }
}

