#include <bits/stdc++.h>
using namespace std;

vector<int> findRightInterval(vector<vector<int>>& intervals) {
    int n = intervals.size();
    vector<pair<int,int>> starts(n);
    for (int i = 0; i < n; i++) starts[i] = {intervals[i][0], i};
    sort(starts.begin(), starts.end());                                // sort once
    vector<int> result(n, -1);
    for (int i = 0; i < n; i++) {
        int end = intervals[i][1];
        int lo = 0, hi = n - 1, ans = -1;
        while (lo <= hi) {                                                // binary search per query
            int mid = (lo + hi) / 2;
            if (starts[mid].first >= end) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        if (ans != -1) result[i] = starts[ans].second;
    }
    return result;
}
